#!/usr/bin/env bash
# VPNSOPR: complete source, blue web theme, and Linux binaries in one file.
# Run on a Linux server with systemd: sudo bash VPNSOPR-ALL.sh
# Export the bundled source without installation: bash VPNSOPR-ALL.sh --extract NEW_DIRECTORY
set -euo pipefail
extract_dir=''
if [[ "${1:-}" == --extract && $# == 2 ]]; then
 extract_dir="$2"
 [[ ! -e "$extract_dir" ]] || { echo 'Choose an extraction directory that does not already exist.'; exit 1; }
elif [[ $# != 0 ]]; then echo 'Usage: bash VPNSOPR-ALL.sh [--extract NEW_DIRECTORY]'; exit 1
fi
for tool in base64 tar mktemp; do command -v "$tool" >/dev/null || { echo "Missing prerequisite: $tool"; exit 1; }; done
if [[ -z "$extract_dir" ]]; then
 [[ "$(uname -s)" == Linux && "$EUID" == 0 ]] || { echo 'Run as root on a Linux server.'; exit 1; }
 [[ -d /run/systemd/system ]] || { echo 'A Linux server booted with systemd is required.'; exit 1; }
 for tool in sha256sum systemctl useradd install id; do command -v "$tool" >/dev/null || { echo "Missing prerequisite: $tool"; exit 1; }; done
fi
work="$(mktemp -d)"; chmod 0700 "$work"; trap 'rm -rf "$work"' EXIT
base64 --decode > "$work/bundle.tar.gz" <<'VPNSOPR_EMBEDDED_ARCHIVE'
